COMMENT ON COLUMN public.students.opening_balance IS 'DEPRECATED: use itemized student_fee_arrears; retained for review, never added twice';
CREATE OR REPLACE FUNCTION public.validate_student_fee_school() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM students s JOIN fee_types f ON f.id=NEW.fee_type_id WHERE s.id=NEW.student_id AND s.school_id=NEW.school_id AND f.school_id=NEW.school_id) THEN RAISE EXCEPTION 'Student and fee must belong to the same school'; END IF; IF NEW.amount<0 OR NEW.amount::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Invalid amount'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_arrears_school BEFORE INSERT OR UPDATE ON public.student_fee_arrears FOR EACH ROW EXECUTE FUNCTION public.validate_student_fee_school();
CREATE TRIGGER validate_invoice_school BEFORE INSERT OR UPDATE ON public.student_invoices FOR EACH ROW EXECUTE FUNCTION public.validate_student_fee_school();
CREATE OR REPLACE FUNCTION public.student_balances(_student uuid) RETURNS TABLE(fee_type_id uuid,name text,account text,due numeric,paid numeric,balance numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH amounts AS (SELECT f.id,f.name,f.account,
coalesce((SELECT sum(i.amount) FROM student_invoices i WHERE i.student_id=s.id AND i.fee_type_id=f.id),0) + CASE WHEN f.active AND f.year=sc.current_year AND f.term=sc.current_term AND (cardinality(f.applies_to)=0 OR s.grade=ANY(f.applies_to)) AND (NOT f.boarding_only OR s.boarding) AND NOT EXISTS(SELECT 1 FROM student_invoices i WHERE i.student_id=s.id AND i.fee_type_id=f.id AND i.year=sc.current_year AND i.term=sc.current_term) THEN f.amount ELSE 0 END + coalesce((SELECT a.amount FROM student_fee_arrears a WHERE a.student_id=s.id AND a.fee_type_id=f.id),0) d,
coalesce((SELECT sum(a.amount) FROM payment_allocations a JOIN payment_receipts r ON r.id=a.receipt_id WHERE a.student_id=s.id AND a.fee_type_id=f.id AND NOT r.voided),0) p
FROM students s JOIN schools sc ON sc.id=s.school_id JOIN fee_types f ON f.school_id=s.school_id WHERE s.id=_student AND public.has_perm(s.school_id,'view') AND ((f.active AND f.year=sc.current_year AND f.term=sc.current_term AND (cardinality(f.applies_to)=0 OR s.grade=ANY(f.applies_to)) AND (NOT f.boarding_only OR s.boarding)) OR EXISTS(SELECT 1 FROM student_fee_arrears a WHERE a.student_id=s.id AND a.fee_type_id=f.id) OR EXISTS(SELECT 1 FROM student_invoices i WHERE i.student_id=s.id AND i.fee_type_id=f.id) OR EXISTS(SELECT 1 FROM payment_allocations a WHERE a.student_id=s.id AND a.fee_type_id=f.id))) SELECT id,name,account,d,p,d-p FROM amounts ORDER BY name $$;
CREATE OR REPLACE FUNCTION public.debtors_by_fee(_school uuid) RETURNS TABLE(student_id uuid,reg_number text,full_name text,grade text,guardian_phone text,fee_type_id uuid,fee_name text,account text,due numeric,paid numeric,balance numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id,s.reg_number,s.first_name||' '||s.last_name,s.grade,s.guardian_phone,b.* FROM students s CROSS JOIN LATERAL public.student_balances(s.id) b WHERE s.school_id=_school AND s.status='active' AND (public.has_perm(_school,'finance') OR public.has_perm(_school,'reports')) $$;
CREATE OR REPLACE FUNCTION public.debtors(_school uuid) RETURNS TABLE(student_id uuid,reg_number text,full_name text,grade text,guardian_phone text,due numeric,paid numeric,balance numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT student_id,reg_number,full_name,grade,guardian_phone,sum(due),sum(paid),sum(balance) FROM public.debtors_by_fee(_school) GROUP BY student_id,reg_number,full_name,grade,guardian_phone ORDER BY sum(balance) DESC $$;
CREATE OR REPLACE FUNCTION public.save_student_arrears(_student uuid,_items jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _sid uuid; _i jsonb; BEGIN SELECT school_id INTO _sid FROM students WHERE id=_student FOR UPDATE; IF _sid IS NULL OR NOT coalesce(public.has_perm(_sid,'finance'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; IF jsonb_typeof(_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid arrears'; END IF; FOR _i IN SELECT * FROM jsonb_array_elements(_items) LOOP IF (_i->>'amount') IS NULL OR (_i->>'amount')::numeric<0 THEN RAISE EXCEPTION 'Invalid amount'; END IF; INSERT INTO student_fee_arrears(school_id,student_id,fee_type_id,amount) VALUES(_sid,_student,(_i->>'fee_type_id')::uuid,(_i->>'amount')::numeric) ON CONFLICT(student_id,fee_type_id) DO UPDATE SET amount=excluded.amount,updated_at=now(); END LOOP; INSERT INTO audit_logs(school_id,user_id,action,record_type,record_id,details) VALUES(_sid,auth.uid(),'student.arrears.updated','student',_student,_items); END $$;
CREATE OR REPLACE FUNCTION public.enrol_student(_school uuid,_student jsonb,_arrears jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; BEGIN IF NOT coalesce(public.has_perm(_school,'students'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; IF coalesce(trim(_student->>'first_name'),'')='' OR coalesce(trim(_student->>'last_name'),'')='' OR coalesce(trim(_student->>'reg_number'),'')='' THEN RAISE EXCEPTION 'Student details required'; END IF; INSERT INTO students(school_id,reg_number,first_name,last_name,gender,grade,class_name,boarding,guardian_name,guardian_phone,opening_balance) VALUES(_school,trim(_student->>'reg_number'),trim(_student->>'first_name'),trim(_student->>'last_name'),nullif(_student->>'gender',''),_student->>'grade',nullif(_student->>'class_name',''),coalesce((_student->>'boarding')::boolean,false),nullif(_student->>'guardian_name',''),nullif(_student->>'guardian_phone',''),0) RETURNING id INTO _id; IF jsonb_array_length(_arrears)>0 THEN PERFORM public.save_student_arrears(_id,_arrears); END IF; RETURN _id; END $$;
ALTER TABLE public.payment_receipts ADD COLUMN client_reference uuid;
ALTER TABLE public.payment_receipts ADD COLUMN client_payload jsonb;
CREATE UNIQUE INDEX receipts_client_reference ON public.payment_receipts(school_id,client_reference) WHERE client_reference IS NOT NULL;
CREATE OR REPLACE FUNCTION public.sync_cash_payment(_school uuid,_student uuid,_client_reference uuid,_paid_on date,_year integer,_term integer,_method text,_reference text,_notes text,_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _rid uuid; _payload jsonb; _existing payment_receipts; BEGIN IF NOT coalesce(public.has_perm(_school,'finance'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; PERFORM 1 FROM schools WHERE id=_school FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM students WHERE id=_student AND school_id=_school) THEN RAISE EXCEPTION 'Student not in this school'; END IF; IF _client_reference IS NULL OR _paid_on IS NULL OR _method NOT IN ('Cash (USD)','Cash (ZiG)') THEN RAISE EXCEPTION 'Offline collection requires cash and a receipt reference'; END IF; IF _year NOT BETWEEN 2000 AND 2200 OR _term NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'Invalid collection period'; END IF; _payload:=jsonb_build_object('student',_student,'date',_paid_on,'year',_year,'term',_term,'method',_method,'reference',_reference,'notes',_notes,'items',_items); SELECT * INTO _existing FROM payment_receipts WHERE school_id=_school AND client_reference=_client_reference; IF FOUND THEN IF _existing.received_by<>auth.uid() OR _existing.client_payload IS DISTINCT FROM _payload THEN RAISE EXCEPTION 'Receipt reference already used with different payment details'; END IF; RETURN _existing.id; END IF; IF jsonb_typeof(_items) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(_items) i WHERE (i->>'amount')::numeric<=0 OR (i->>'amount')::numeric<>round((i->>'amount')::numeric,2) OR (i->>'amount')::text IN ('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'Invalid payment amounts'; END IF; _rid:=public.collect_payment(_student,_method,_reference,_notes,_paid_on,_items); UPDATE payment_receipts SET client_reference=_client_reference,client_payload=_payload,year=_year,term=_term WHERE id=_rid; RETURN _rid; END $$;
REVOKE ALL ON FUNCTION public.save_student_arrears(uuid,jsonb),public.enrol_student(uuid,jsonb,jsonb),public.sync_cash_payment(uuid,uuid,uuid,date,integer,integer,text,text,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_student_arrears(uuid,jsonb),public.enrol_student(uuid,jsonb,jsonb),public.sync_cash_payment(uuid,uuid,uuid,date,integer,integer,text,text,text,jsonb) TO authenticated,service_role;